# Generate XLSX report directly using the model method report_model = env['ks.part.wise.all.data.report'] file_content = report_model.generate_xlsx_report()
# Create attachment to store the file attachment = env['ir.attachment'].create({ 'name': 'Part_Wise_All_Data.xlsx', 'type': 'binary', 'datas': file_content, 'res_model': 'sale.order', 'mimetype': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', })
# Return download action action = { 'type': 'ir.actions.act_url', 'url': '/web/content/' + str(attachment.id) + '?download=true', 'target': 'self', }

